def unique_in_order(event_ids):
    seen = set()
    result = []
    for event_id in event_ids:
        if event_id not in seen:
            seen.add(event_id)
            result.append(event_id)
    return result

print(unique_in_order(['x', 'y', 'x', 'z']))
